/** WS03-PIM: producto 9(4) + instrumento 9(4) + moneda 9(3) leído como una sola clave de 11 dígitos. */
public record Pim(int producto, int instrumento, int moneda) {
    public String clave() { return "%04d%04d%03d".formatted(producto, instrumento, moneda); }
}

