// ---------------------------------------------------------------------------
@ConfigurationProperties("p199.librerias")
public record LibreriasProperties(boolean saldosL301, boolean consultasL190) {}

@Component
@RequiredArgsConstructor
class ValidaPerfilProduccion implements ApplicationListener<ApplicationReadyEvent> {
    private final Environment env;
    private final LibreriasProperties libs;

    @Override
    public void onApplicationEvent(ApplicationReadyEvent e) {
        boolean prod = env.acceptsProfiles(Profiles.of("prod"));
        if (prod && !(libs.saldosL301() && libs.consultasL190())) {
            throw new IllegalStateException("EN PRODUCCION NO CORRE SIN LIBRERIAS S050");
        }
    }
}

@Component
@RequiredArgsConstructor
public class YaCorrioDecider implements JobExecutionDecider {

    private final ControlCaptacionRepository b02;

    /** B02-STA-OTRINV: 1 proceso completo, 2 incompleto por fin forzado. */
    @Override
    public FlowExecutionStatus decide(JobExecution job, StepExecution step) {
        int estatus = b02.findEstatusOtrasInversiones()
                .orElseThrow(() -> new ProcesoAbortadoException("ERR FIND B02CONTROL"));
        return (estatus == 1)
                ? new FlowExecutionStatus("YA_CORRIO")      // W77-REINICIO = 9: solo informa
                : new FlowExecutionStatus("PROCESAR");      // 0 o 2: recorre B03 completo
    }
}

@Bean
Job cargaOtrasInversiones(JobRepository repo, YaCorrioDecider decider,
                          Step cargaSaldos, Step marcaControl, Step informaYaCorrio) {
    return new JobBuilder("S500P199", repo)
            .start(decider)
            .on("YA_CORRIO").to(informaYaCorrio)
            .from(decider).on("PROCESAR").to(cargaSaldos).next(marcaControl)   // 59000000
            .end().build();
}

@Component
@StepScope
@RequiredArgsConstructor
public class ContratoCorteFilter implements ItemProcessor<Contrato, ContratoACargar> {

    private final CatalogoInstrumentos catalogo;
    private final P199Properties props;
    private final FechaCorte fechaCorte;

    @Override
    public ContratoACargar process(Contrato c) {
        if (c.marcaClon() == 3) return null;                               // extended: solo se cuenta
        boolean vigente = (c.status() < 2 || c.status() == 5) && c.migradoS111() != 1;
        if (!vigente || props.esAhorros(c.pim())) return null;

        int persona = c.tipoPersona().esFisica() ? 1 : 2;                 // W77-IND-PERS
        if (!fechaCorte.cortaEnVentana(c)) return null;                   // 50003160-VALIDA-CORTE

        var inst = catalogo.busca(c.pim()).orElse(null);
        if (inst == null) {
            log.warn("NO EXISTE EN B05 {} {}", c.pim(), c.numContrato());
            return null;
        }
        boolean saldos = inst.saldosIntegrados(persona);                  // WKS-TB-B05-SI-SDOSINTEG
        boolean consultas = CatalogoInstrumentos.usaTarifasL190(inst);
        return (saldos || consultas)
                ? new ContratoACargar(c, inst, persona, saldos, consultas) : null;
    }
}

@Component
@StepScope
public class FechaCorte {

    @Value("#{jobExecutionContext['fechaBatch']}")     private LocalDate fechaBatch;
    @Value("#{jobExecutionContext['fechaSiguiente']}") private LocalDate fechaSiguiente;   // WKS-FEC-PROX

    /** Corta si la fecha de corte es la del batch o cae después y antes del siguiente día de proceso. */
    boolean cortaEnVentana(Contrato c) {
        LocalDate nuevo = proyecta(c.diaCorte());
        LocalDate efectiva = (c.diaCorteAnterior() > 0)
                ? min(proyecta(c.diaCorteAnterior()), nuevo)                // cambio de día de corte
                : nuevo;
        return efectiva.equals(fechaBatch)
                || (efectiva.isAfter(fechaBatch) && efectiva.isBefore(fechaSiguiente));
    }

    /** 50003160-ARMA-FEC-CORTE: día 30 significa último día del mes; si ya pasó, mes siguiente. */
    LocalDate proyecta(int diaCorte) {
        YearMonth mes = YearMonth.from(fechaBatch);
        int dia = (diaCorte == 30) ? mes.lengthOfMonth() : diaCorte;
        if (dia < fechaBatch.getDayOfMonth()) {
            mes = mes.plusMonths(1);
        }
        return mes.atDay(Math.min(dia, mes.lengthOfMonth()));   // ver riesgo: el COBOL no acota
    }
}

@Component
@RequiredArgsConstructor
public class CargaOtrasInversionesProcessor
        implements ItemProcessor<ContratoACargar, Historico> {

    private final SaldosOtrasInversionesClient s050;   // S050/L301 vía 20000050-SALDOS
    private final HistoricoRepository b06;
    private final MeterRegistry metricas;

    @Override
    public Historico process(ContratoACargar c) {
        Historico h = b06.findByContratoForUpdate(c.numContrato())       // 50003200: LOCK B06
                .orElseThrow(() -> new ProcesoAbortadoException("FALTA HISTORICO " + c.numContrato()));
        if (h.idS050() != 0) {
            return null;                                                 // ya cargado en corrida previa
        }
        if (c.saldos()) {
            var r = s050.saldos(c.pim(), c.numContrato());
            h.marcaCargadoS050();                                        // B06-ID-S050 = 1
            boolean alguno = false;
            if (c.instrumento().usaInversionIntegral(c.persona()) && r.fondos().ok()) {
                h.setSaldoFondos(r.fondos().importe());                  // BigDecimal, escala del PIC destino
                alguno = true;
            }
            // ... banca de inversión, plazo y mesa de dinero con el mismo patrón
            r.fondos().errorFatal().ifPresent(e -> { throw new S050NoDisponibleException(e); });
            metricas.counter(alguno ? "p199.si.s050" : "p199.no.s050").increment();
        }
        return h;
    }
}

@Component
@RequiredArgsConstructor
public class ConsultasEdoCtaClient {

    private final TarifasL190Gateway l190;            // S050/L190 COBCOM, proceso 1
    private final RetryTemplate s050NoDisponible;     // 4 intentos con 60 s; luego intervención
    private final OperadorService operador;           // 70000055-STOP-PGM

    /** 50005100-PIDE-CONSULTAS + 50005200-ACTUALIZA-CONSULTA. */
    void cargaContadores(Historico h, Pim pim, String contrato) {
        var r = s050NoDisponible.execute(
                ctx -> l190.consultas(pim, contrato),
                ctx -> { operador.esperaConfirmacion("BASE S050 NO DISPONIBLE"); return l190.consultas(pim, contrato); });
        h.marcaCargadoS050();
        switch (r.resultado()) {
            case OK -> {
                h.setContadorComision(12, r.contador(1));
                h.setContadorComision(13, r.contador(2));
                h.setContadorComision(6,  r.contador(6));
            }
            case SIN_INFORMACION -> { }                                       // nada que cargar
            default -> log.warn("ERR CALL S050/L190 RS={} {} {}", r.codigo(), pim, contrato);
        }
    }
}

@Bean
Step cargaSaldos(JobRepository repo, PlatformTransactionManager tx,
                 RepositoryItemReader<Contrato> contratos,       // S500B03CONTRATOS en orden físico
                 CompositeItemProcessor<Contrato, Historico> procesador,
                 JpaItemWriter<Historico> historico) {
    return new StepBuilder("cargaSaldos", repo)
            .<Contrato, Historico>chunk(1, tx)      // BEGIN/END TRANSACTION por contrato
            .reader(contratos)
            .processor(procesador)                  // filtro + saldos + consultas
            .writer(historico)                      // 90000006-B06HISTORICO-STORE
            .build();
    // Un error de STORE lanza excepción y el step queda FAILED (antes CALL SYSTEM DMTERMINATE).
}
